catalog_script_client.script:
function onSubmit() {
    cleanCurrency('v_despesa_bruta_com_pessoal');
    cleanCurrency('v_despesa_com_pessoal_ativo');
    cleanCurrency('v_despesa_com_pessoal_inativo_e_pensionistas');
    cleanCurrency('v_despesa_com_pessoal_terceirizado');
    cleanCurrency('v_despesa_com_deducoes');
    cleanCurrency('v_indenizacoes_por_demissao_ou_por_incentivo_a_demissao_voluntaria');
    cleanCurrency('v_despesas_com_indenizaces_de_decisoes_judiciais');
    cleanCurrency('v_despesas_de_exercicio_anteriores');
    cleanCurrency('v_interface_a_pensionistas_com_resumos_vinculados');
    cleanCurrency('v_despesa_liquida_com_pedidos');
    cleanCurrency('v_receita_corrente_liquidos_sel_7406a_fibo_de_medidas');
    cleanCurrency('v_porcentagem_do_limite_maximo_de_rcl');
    cleanCurrency('v_porcentagem_de_comprometimento_de_rcl');
    cleanCurrency('v_porcentagem_do_limite_prudencial_de_rcl');
    cleanCurrency('v_porcentagem_de_limite_de_alerta_de_rcl');
    cleanCurrency('v_receita_corrente_liquida_rcl');
    cleanCurrency('v_despesa_total_com_pessoal_executivo_anual');
    cleanCurrency('v_despesa_liquida_pessoal_consolidado');
    cleanCurrency('v_despesa_liquida_pessoal_executivo');

    return true;
}

function cleanCurrency(variableName) {
    let value = g_form.getValue(variableName);
    if (!value) return;
    value = value.replace(/[R$\s\.]/g, '').replace(',', '.');
    g_form.setValue(variableName, value);
}
